/* @lc app=leetcode id=3762 lang=kotlin */ class Solution { fun ins(lc: IntArray, rc: IntArray, cn: IntArray, sm: LongArray, nx: IntArray, prev: Int, lo: Int, hi: Int, pos: Int, v: Long): Int = nx[0].also { nx[0] = it + 1 }.let { nd -> cn.set(nd, cn[prev] + 1).also { sm[nd] = sm[prev] + v }.also { if (lo < hi) ((lo + hi) / 2).let { mid -> if (pos <= mid) lc.set(nd, ins(lc, rc, cn, sm, nx, lc[prev], lo, mid, pos, v)).also { rc[nd] = rc[prev] } else rc.set(nd, ins(lc, rc, cn, sm, nx, rc[prev], mid + 1, hi, pos, v)).also { lc[nd] = lc[prev] } } else Unit }.let { nd } } fun kth(lc: IntArray, rc: IntArray, cn: IntArray, sm: LongArray, vals: List<Int>, ra: Int, rb: Int, m: Int, k: Int): LongArray = generateSequence(longArrayOf(ra.toLong(), rb.toLong(), 0L, m - 1L, k.toLong(), 0L, 0L)) { s -> if (s[2] == s[3]) null else ((s[2] + s[3]) / 2).let { mid -> (cn[lc[s[1].toInt()]] - cn[lc[s[0].toInt()]]).let { lcnt -> if (s[4] <= lcnt) longArrayOf(lc[s[0].toInt()].toLong(), lc[s[1].toInt()].toLong(), s[2], mid, s[4], s[5], s[6]) else longArrayOf(rc[s[0].toInt()].toLong(), rc[s[1].toInt()].toLong(), mid + 1, s[3], s[4] - lcnt, s[5] + lcnt, s[6] + (sm[lc[s[1].toInt()]] - sm[lc[s[0].toInt()]])) } } }.last().let { s -> (cn[s[1].toInt()] - cn[s[0].toInt()]).let { leafC -> vals[s[2].toInt()].toLong().let { med -> longArrayOf(med, s[5] + leafC, s[6] + leafC * med) } } } fun minOperations(nums: IntArray, k: Int, queries: Array<IntArray>): LongArray = nums.size.let { n -> nums.map { it / k }.let { b -> nums.map { it % k }.let { rm -> rm.indices.runningFold(0) { c, i -> if (i > 0 && rm[i] != rm[i - 1]) c + 1 else c }.drop(1).let { ch -> b.distinct().sorted().let { vals -> IntArray(n * 20 + 5).let { lc -> IntArray(n * 20 + 5).let { rc -> IntArray(n * 20 + 5).let { cn -> LongArray(n * 20 + 5).let { sm -> IntArray(1) { 1 }.let { nx -> (0 until n).runningFold(0) { prev, i -> ins(lc, rc, cn, sm, nx, prev, 0, vals.size - 1, vals.binarySearch(b[i]), b[i].toLong()) }.let { roots -> queries.map { (l, r) -> if (ch[r] != ch[l]) -1L else kth(lc, rc, cn, sm, vals, roots[l], roots[r + 1], vals.size, (r - l + 2) / 2).let { (med, cle, sle) -> (sm[roots[r + 1]] - sm[roots[l]]).let { tot -> med * cle - sle + (tot - sle) - med * ((r - l + 1) - cle) } } }.toLongArray() } } } } } } } } } } } }